-- a code from free text: "Vendor Payment" -> VendorPayment
CREATE OR ALTER   FUNCTION dbo.fn_approval_code (@text NVARCHAR(200))
RETURNS NVARCHAR(50)
AS
BEGIN
    DECLARE @out NVARCHAR(200) = N'', @i INT = 1, @c NCHAR(1), @up BIT = 1;
    SET @text = LTRIM(RTRIM(ISNULL(@text, N'')));
    WHILE @i <= LEN(@text)
    BEGIN
        SET @c = SUBSTRING(@text, @i, 1);
        IF @c LIKE N'[A-Za-z0-9]'
        BEGIN
            SET @out = @out + CASE WHEN @up = 1 THEN UPPER(@c) ELSE @c END;
            SET @up = 0;
        END
        ELSE SET @up = 1;
        SET @i += 1;
    END;
    RETURN LEFT(@out, 50);
END;

-- ── 3. First required stage after @after (NULL = none left) ─────────────────
CREATE OR ALTER   FUNCTION dbo.fn_approval_next_seq
(
    @stages  NVARCHAR(MAX),
    @after   INT,
    @context NVARCHAR(MAX)
)
RETURNS INT
AS
BEGIN
    DECLARE @next INT;
    SELECT TOP 1 @next = CAST(s.[key] AS INT)
    FROM OPENJSON(@stages) s
    WHERE CAST(s.[key] AS INT) > @after
      AND dbo.fn_approval_condition_met(JSON_QUERY(s.value, '$.condition'), @context) = 1
    ORDER BY CAST(s.[key] AS INT);
    RETURN @next;
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_MarkApproverChangeNoticeSent
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    UPDATE dbo.approver_reassignment_log
    SET status = CASE WHEN JSON_VALUE(@jsonInput, '$.status') = 'SENT' THEN 'SENT' ELSE 'FAILED' END,
        error_message = LEFT(JSON_VALUE(@jsonInput, '$.error_message'), 500),
        modified_at = GETDATE()
    WHERE notice_sno = TRY_CAST(JSON_VALUE(@jsonInput, '$.notice_sno') AS INT);
END;

CREATE OR ALTER   PROCEDURE dbo.sp_nt_UploadServiceAgreementSignedDoc
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @agreement_sno INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.agreement_sno') AS INT),
            @doc_url NVARCHAR(500) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.doc_url'))), ''),
            @remarks NVARCHAR(500) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.remarks'))), ''),
            @uploaded_by VARCHAR(50) = JSON_VALUE(@jsonInput, '$.uploaded_by'),
            @status VARCHAR(5), @version_no INT;

    IF @agreement_sno IS NULL THROW 58301, 'agreement_sno is required', 1;
    IF @doc_url IS NULL THROW 58302, 'The signed agreement file is required', 1;
    IF @uploaded_by IS NULL THROW 58303, 'uploaded_by is required', 1;

    SELECT @status = status FROM dbo.service_agreement WHERE agreement_sno = @agreement_sno;
    SELECT @version_no = MAX(version_no) FROM dbo.service_agreement_version WHERE agreement_sno = @agreement_sno;
    IF @status IS NULL THROW 58304, 'Service agreement not found', 1;
    IF @status <> 'A' THROW 58305, 'The signed copy can only be uploaded once the agreement is approved', 1;

    INSERT dbo.service_agreement_signed_doc (agreement_sno, version_no, doc_url, remarks, uploaded_by)
    VALUES (@agreement_sno, @version_no, @doc_url, @remarks, @uploaded_by);

    SELECT SCOPE_IDENTITY() AS signed_doc_sno, @agreement_sno AS agreement_sno;
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_GetServiceAgreementSignedDocs
    @jsonInput NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @agreement_sno INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.agreement_sno') AS INT);
    SELECT signed_doc_sno, agreement_sno, version_no, doc_url, remarks, uploaded_by, uploaded_at
    FROM dbo.service_agreement_signed_doc
    WHERE is_active = 'Y' AND (@agreement_sno IS NULL OR agreement_sno = @agreement_sno)
    ORDER BY uploaded_at DESC, signed_doc_sno DESC;
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_UploadServicePoInvoice
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @po_basic_sno INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.po_basic_sno') AS INT),
            @invoice_no NVARCHAR(100) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.invoice_no'))), ''),
            @invoice_date DATE = TRY_CAST(JSON_VALUE(@jsonInput, '$.invoice_date') AS DATE),
            @invoice_amount DECIMAL(18,2) = TRY_CAST(JSON_VALUE(@jsonInput, '$.invoice_amount') AS DECIMAL(18,2)),
            @doc_url NVARCHAR(500) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.invoice_doc_url'))), ''),
            @remarks NVARCHAR(500) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.remarks'))), ''),
            @uploaded_by VARCHAR(50) = JSON_VALUE(@jsonInput, '$.uploaded_by'),
            @cycle_sno INT, @agreement_sno INT, @vendor_sno INT;

    IF @po_basic_sno IS NULL THROW 58311, 'po_basic_sno is required', 1;
    IF @invoice_no IS NULL THROW 58312, 'Invoice number is required', 1;
    IF @invoice_date IS NULL THROW 58313, 'A valid invoice date is required', 1;
    IF @invoice_date > CAST(GETDATE() AS DATE) THROW 58314, 'Invoice date cannot be in the future', 1;
    IF @invoice_amount IS NULL OR @invoice_amount <= 0 THROW 58315, 'Invoice amount must be greater than zero', 1;
    IF @doc_url IS NULL THROW 58316, 'The invoice file is required', 1;
    IF @uploaded_by IS NULL THROW 58317, 'uploaded_by is required', 1;

    -- the PO must have been raised by an approved (GENERATED) service cycle
    SELECT TOP 1 @cycle_sno = c.cycle_sno, @agreement_sno = c.agreement_sno, @vendor_sno = cv.vendor_sno
    FROM dbo.service_po_cycle c
    LEFT JOIN dbo.service_po_cycle_vendor cv ON cv.cycle_sno = c.cycle_sno AND cv.po_basic_sno = @po_basic_sno
    WHERE c.status = 'GENERATED' AND (c.po_basic_sno = @po_basic_sno OR cv.po_basic_sno = @po_basic_sno)
    ORDER BY c.cycle_sno DESC;
    IF @cycle_sno IS NULL THROW 58318, 'This is not an approved Service PO', 1;

    IF @vendor_sno IS NULL SELECT @vendor_sno = vendor_sno FROM dbo.service_agreement WHERE agreement_sno = @agreement_sno;

    IF EXISTS (SELECT 1 FROM dbo.service_po_invoice WHERE po_basic_sno = @po_basic_sno AND invoice_no = @invoice_no AND is_active = 'Y')
        THROW 58319, 'This invoice number is already uploaded against the PO', 1;

    INSERT dbo.service_po_invoice (po_basic_sno, cycle_sno, agreement_sno, vendor_sno, invoice_no, invoice_date, invoice_amount, invoice_doc_url, remarks, uploaded_by)
    VALUES (@po_basic_sno, @cycle_sno, @agreement_sno, @vendor_sno, @invoice_no, @invoice_date, @invoice_amount, @doc_url, @remarks, @uploaded_by);

    SELECT SCOPE_IDENTITY() AS invoice_sno, @po_basic_sno AS po_basic_sno, @cycle_sno AS cycle_sno, @agreement_sno AS agreement_sno;
END

-- ============================================================================
-- TransportMaster (nt_transport_master). Update/Delete already exist and are
-- correct (sp_nt_UpdateTransportRecords / sp_nt_DeleteTransportRecords) â€”
-- only Create is rewritten here, to be bulk-safe.
-- ============================================================================
CREATE OR ALTER   PROCEDURE dbo.sp_nt_CreateTransportRecords
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0
        THROW 50000, N'Invalid JSON payload provided.', 1;

    DECLARE @json NVARCHAR(MAX) = CASE WHEN LEFT(LTRIM(@jsonInput), 1) = '[' THEN @jsonInput ELSE '[' + @jsonInput + ']' END;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (transport_name VARCHAR(255) '$.transport_name')
        WHERE transport_name IS NULL OR LTRIM(RTRIM(transport_name)) = ''
    )
        THROW 50001, N'transport_name is required for every row.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (transport_name VARCHAR(255) '$.transport_name') j
        JOIN dbo.nt_transport_master m ON m.transport_name = j.transport_name AND m.is_active = 'Y'
    )
        THROW 50002, N'A transporter with this name already exists.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @NextSeq INT = ISNULL((SELECT MAX(transport_sno) FROM dbo.nt_transport_master), 0);

        DECLARE @Rows TABLE (rn INT IDENTITY(1,1), transport_code VARCHAR(50), transport_name VARCHAR(255), contact_person VARCHAR(100), phone_no VARCHAR(20), gst_no VARCHAR(20), address VARCHAR(255), created_by VARCHAR(20));
        INSERT INTO @Rows (transport_code, transport_name, contact_person, phone_no, gst_no, address, created_by)
        SELECT
            CASE WHEN transport_code IS NULL OR LTRIM(RTRIM(transport_code)) = '' THEN NULL ELSE LTRIM(RTRIM(transport_code)) END,
            transport_name, contact_person, phone_no, gst_no, address, created_by
        FROM OPENJSON(@json)
        WITH (
            transport_code VARCHAR(50)  '$.transport_code',
            transport_name VARCHAR(255) '$.transport_name',
            contact_person VARCHAR(100) '$.contact_person',
            phone_no       VARCHAR(20)  '$.phone_no',
            gst_no         VARCHAR(20)  '$.gst_no',
            address        VARCHAR(255) '$.address',
            created_by     VARCHAR(20)  '$.created_by'
        );

        UPDATE @Rows
        SET transport_code = 'TRN-' + RIGHT('0000' + CAST(@NextSeq + rn AS VARCHAR(4)), 4)
        WHERE transport_code IS NULL;

        DECLARE @Inserted TABLE (transport_sno INT);

        INSERT INTO dbo.nt_transport_master (transport_code, transport_name, contact_person, phone_no, gst_no, address, is_active, created_by)
        OUTPUT INSERTED.transport_sno INTO @Inserted
        SELECT transport_code, transport_name, contact_person, phone_no, gst_no, address, 'Y', created_by
        FROM @Rows
        ORDER BY rn;

        COMMIT TRANSACTION;

        SELECT t.* FROM dbo.nt_transport_master t JOIN @Inserted i ON i.transport_sno = t.transport_sno;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_AttachServicePoEntryInvoice
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @cycle_sno INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.cycle_sno') AS INT),
            @invoice_no NVARCHAR(100) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.invoice_no'))), ''),
            @invoice_date DATE = TRY_CAST(JSON_VALUE(@jsonInput, '$.invoice_date') AS DATE),
            @invoice_amount DECIMAL(18,2) = TRY_CAST(JSON_VALUE(@jsonInput, '$.invoice_amount') AS DECIMAL(18,2)),
            @doc_url NVARCHAR(500) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.invoice_doc_url'))), ''),
            @remarks NVARCHAR(500) = NULLIF(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.remarks'))), ''),
            @uploaded_by VARCHAR(50) = JSON_VALUE(@jsonInput, '$.uploaded_by'),
            @agreement_sno INT, @vendor_sno INT;

    IF @cycle_sno IS NULL THROW 58321, 'cycle_sno is required', 1;
    IF @invoice_no IS NULL THROW 58312, 'Invoice number is required', 1;
    IF @invoice_date IS NULL THROW 58313, 'A valid invoice date is required', 1;
    IF @invoice_date > CAST(GETDATE() AS DATE) THROW 58314, 'Invoice date cannot be in the future', 1;
    IF @invoice_amount IS NULL OR @invoice_amount <= 0 THROW 58315, 'Invoice amount must be greater than zero', 1;
    IF @doc_url IS NULL THROW 58316, 'The invoice file is required', 1;
    IF @uploaded_by IS NULL THROW 58317, 'uploaded_by is required', 1;

    SELECT @agreement_sno = agreement_sno FROM dbo.service_po_cycle WHERE cycle_sno = @cycle_sno;
    IF @agreement_sno IS NULL THROW 58322, 'Service PO cycle not found', 1;

    -- single-supplier agreement: the supplier is known; a split cycle's invoice is not tied to one
    IF (SELECT COUNT(*) FROM dbo.service_agreement_vendor WHERE agreement_sno = @agreement_sno) = 1
        SELECT @vendor_sno = vendor_sno FROM dbo.service_agreement_vendor WHERE agreement_sno = @agreement_sno;

    IF EXISTS (SELECT 1 FROM dbo.service_po_invoice WHERE cycle_sno = @cycle_sno AND po_basic_sno IS NULL AND invoice_no = @invoice_no AND is_active = 'Y')
        THROW 58319, 'This invoice number is already uploaded for this cycle', 1;

    INSERT dbo.service_po_invoice (po_basic_sno, cycle_sno, agreement_sno, vendor_sno, invoice_no, invoice_date, invoice_amount, invoice_doc_url, remarks, uploaded_by)
    VALUES (NULL, @cycle_sno, @agreement_sno, @vendor_sno, @invoice_no, @invoice_date, @invoice_amount, @doc_url, @remarks, @uploaded_by);

    SELECT SCOPE_IDENTITY() AS invoice_sno, @cycle_sno AS cycle_sno;
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_CreateUomClassRecords
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0
        THROW 50000, N'Invalid JSON payload provided.', 1;

    DECLARE @json NVARCHAR(MAX) = CASE WHEN LEFT(LTRIM(@jsonInput), 1) = '[' THEN @jsonInput ELSE '[' + @jsonInput + ']' END;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (uom_class_code NVARCHAR(30) '$.uom_class_code', uom_class_name NVARCHAR(100) '$.uom_class_name')
        WHERE LTRIM(RTRIM(ISNULL(uom_class_code, N''))) = N'' OR LTRIM(RTRIM(ISNULL(uom_class_name, N''))) = N''
    )
        THROW 50002, N'uom_class_code and uom_class_name are required for every row.', 1;

    -- Codes are stored upper-case: they are compared as plain strings by
    -- Product Master / GRN unit conversion.
    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (uom_class_code NVARCHAR(30) '$.uom_class_code') j
        JOIN dbo.uom_class_master m ON m.uom_class_code = UPPER(LTRIM(RTRIM(j.uom_class_code)))
    )
        THROW 50003, N'A UOM class with this code already exists.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (uom_class_name NVARCHAR(100) '$.uom_class_name') j
        JOIN dbo.uom_class_master m ON m.uom_class_name = LTRIM(RTRIM(j.uom_class_name))
    )
        THROW 50004, N'A UOM class with this name already exists.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @Inserted TABLE (uom_class_sno INT);

        INSERT INTO dbo.uom_class_master (uom_class_code, uom_class_name, is_active, created_by)
        OUTPUT INSERTED.uom_class_sno INTO @Inserted
        SELECT UPPER(LTRIM(RTRIM(uom_class_code))), LTRIM(RTRIM(uom_class_name)), 'Y', created_by
        FROM OPENJSON(@json)
        WITH (
            uom_class_code NVARCHAR(30)  '$.uom_class_code',
            uom_class_name NVARCHAR(100) '$.uom_class_name',
            created_by     VARCHAR(20)   '$.created_by'
        );

        COMMIT TRANSACTION;

        SELECT t.* FROM dbo.uom_class_master t JOIN @Inserted i ON i.uom_class_sno = t.uom_class_sno;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_UpdateUomClassRecords
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @id INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.id') AS INT);
    IF @id IS NULL SET @id = TRY_CAST(JSON_VALUE(@jsonInput, '$.uom_class_sno') AS INT);

    IF @id IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.uom_class_master WHERE uom_class_sno = @id)
        THROW 50005, N'UOM class not found.', 1;

    DECLARE @oldCode VARCHAR(30) = (SELECT uom_class_code FROM dbo.uom_class_master WHERE uom_class_sno = @id);
    DECLARE @newCode VARCHAR(30) = UPPER(LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.uom_class_code'))));
    DECLARE @newName NVARCHAR(100) = LTRIM(RTRIM(JSON_VALUE(@jsonInput, '$.uom_class_name')));

    IF @newCode = '' SET @newCode = NULL;
    IF @newName = N'' SET @newName = NULL;

    IF @newCode IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.uom_class_master WHERE uom_class_code = @newCode AND uom_class_sno <> @id)
        THROW 50003, N'A UOM class with this code already exists.', 1;
    IF @newName IS NOT NULL AND EXISTS (SELECT 1 FROM dbo.uom_class_master WHERE uom_class_name = @newName AND uom_class_sno <> @id)
        THROW 50004, N'A UOM class with this name already exists.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE dbo.uom_class_master
        SET uom_class_code = ISNULL(@newCode, uom_class_code),
            uom_class_name = ISNULL(@newName, uom_class_name),
            modified_by    = JSON_VALUE(@jsonInput, '$.modified_by'),
            modified_at    = GETDATE()
        WHERE uom_class_sno = @id;

        -- uom_master stores the class code as a string — carry a rename across.
        IF @newCode IS NOT NULL AND @newCode <> @oldCode
            UPDATE dbo.uom_master SET uom_class = @newCode WHERE uom_class = @oldCode;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH

    SELECT * FROM dbo.uom_class_master WHERE uom_class_sno = @id;
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_DeleteUomClassRecords
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @id INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.id') AS INT);

    IF @id IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.uom_class_master WHERE uom_class_sno = @id)
        THROW 50005, N'UOM class not found.', 1;

    IF EXISTS (
        SELECT 1 FROM dbo.uom_master u
        JOIN dbo.uom_class_master c ON c.uom_class_code = u.uom_class
        WHERE c.uom_class_sno = @id AND u.is_active = 'Y'
    )
        THROW 50006, N'This UOM class is still used by active units of measurement — move or remove them first.', 1;

    UPDATE dbo.uom_class_master SET is_active = 'N', modified_at = GETDATE() WHERE uom_class_sno = @id;
    SELECT @id AS uom_class_sno, 'N' AS is_active, 'SUCCESS' AS status;
END

-- ============================================================
-- Terms & Conditions — list every active entry for an exact scope
-- Database: Non_Trade (MSSQL)
--
-- PO creation used to receive only the single is_default='Y' entry
-- (sp_nt_GetDefaultTermsConditions). The buyer can now also pick any other
-- active entry configured for the same Company/Division/Branch/Department,
-- so this returns all of them, default first.
-- @jsonInput: {"com_sno":1, "div_sno":2, "brn_sno":3, "dept_sno":4}
-- ============================================================
CREATE OR ALTER   PROCEDURE dbo.sp_nt_GetTermsConditionsForScope
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @com_sno  INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.com_sno')  AS INT),
            @div_sno  INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.div_sno')  AS INT),
            @brn_sno  INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.brn_sno')  AS INT),
            @dept_sno INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.dept_sno') AS INT);

    SELECT tc_sno, tc_title, tc_text, is_default
    FROM dbo.terms_conditions_master
    WHERE com_sno = @com_sno AND div_sno = @div_sno AND brn_sno = @brn_sno AND dept_sno = @dept_sno
      AND is_active = 'Y'
    ORDER BY CASE WHEN is_default = 'Y' THEN 0 ELSE 1 END, tc_title;
END;

-- ============================================================================
-- ProductSubCategoryMaster (subcategory_master: subcat_sno PK, subcat_active)
-- ============================================================================
CREATE OR ALTER   PROCEDURE dbo.sp_nt_CreateSubCategoryRecords
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0
        THROW 50000, N'Invalid JSON payload provided.', 1;

    DECLARE @json NVARCHAR(MAX) = CASE WHEN LEFT(LTRIM(@jsonInput), 1) = '[' THEN @jsonInput ELSE '[' + @jsonInput + ']' END;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (cat_sno INT '$.cat_sno', subcat_name NVARCHAR(50) '$.subcat_name')
        WHERE cat_sno IS NULL OR subcat_name IS NULL OR LTRIM(RTRIM(subcat_name)) = ''
    )
        THROW 50002, N'cat_sno and subcat_name are required for every row.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json)
        WITH (subcat_stock_type VARCHAR(20) '$.subcat_stock_type')
        WHERE ISNULL(NULLIF(subcat_stock_type, ''), 'Regular') NOT IN ('Regular', 'Non-Regular', 'Perishable')
    )
        THROW 50005, N'subcat_stock_type must be Regular, Non-Regular or Perishable.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json)
        WITH (subcat_stock_type VARCHAR(20) '$.subcat_stock_type', perishable_days INT '$.perishable_days')
        WHERE ISNULL(NULLIF(subcat_stock_type, ''), 'Regular') = 'Perishable' AND (perishable_days IS NULL OR perishable_days <= 0)
    )
        THROW 50006, N'perishable_days is required and must be greater than zero when subcat_stock_type is Perishable.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (cat_sno INT '$.cat_sno') j
        LEFT JOIN dbo.category_master cm ON cm.cat_sno = j.cat_sno AND cm.cat_active = 'Y'
        WHERE cm.cat_sno IS NULL
    )
        THROW 50003, N'Category not found.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (cat_sno INT '$.cat_sno', subcat_name NVARCHAR(50) '$.subcat_name') j
        JOIN dbo.subcategory_master m ON m.cat_sno = j.cat_sno AND m.subcat_name = j.subcat_name AND m.subcat_active = 'Y'
    )
        THROW 50004, N'A sub category with this name already exists under the selected category.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @Inserted TABLE (subcat_sno INT);

        INSERT INTO dbo.subcategory_master (cat_sno, subcat_name, subcat_description, subcat_notes, subcat_stock_type, perishable_days, subcat_active, subcat_created_date, subcat_created_by)
        OUTPUT INSERTED.subcat_sno INTO @Inserted
        SELECT
            cat_sno, subcat_name, subcat_description, subcat_notes,
            ISNULL(NULLIF(subcat_stock_type, ''), 'Regular'),
            CASE WHEN ISNULL(NULLIF(subcat_stock_type, ''), 'Regular') = 'Perishable' THEN perishable_days ELSE NULL END,
            'Y', GETDATE(), created_by
        FROM OPENJSON(@json)
        WITH (
            cat_sno            INT           '$.cat_sno',
            subcat_name        NVARCHAR(50)  '$.subcat_name',
            subcat_description NVARCHAR(100) '$.subcat_description',
            subcat_notes       NVARCHAR(500) '$.subcat_notes',
            subcat_stock_type  VARCHAR(20)   '$.subcat_stock_type',
            perishable_days    INT           '$.perishable_days',
            created_by         VARCHAR(20)   '$.created_by'
        );

        COMMIT TRANSACTION;

        SELECT t.* FROM dbo.subcategory_master t JOIN @Inserted i ON i.subcat_sno = t.subcat_sno;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

-- entity list now carries route_module_code
CREATE OR ALTER   PROCEDURE dbo.sp_nt_GetEntityRecords
AS
BEGIN
    SET NOCOUNT ON;
    SELECT entity_sno, entity_name, entity_code, entity_desc, is_active, route_module_code
    FROM dbo.entity_master
    WHERE is_active = 'Y'
    ORDER BY entity_name;
END;

-- ============================================================================
-- SupplierCatagoryMaster (supplier_category: supp_cat_sno PK, is_active)
-- ============================================================================
CREATE OR ALTER   PROCEDURE dbo.sp_nt_CreateSupplierCategoryRecords
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0
        THROW 50000, N'Invalid JSON payload provided.', 1;

    DECLARE @json NVARCHAR(MAX) = CASE WHEN LEFT(LTRIM(@jsonInput), 1) = '[' THEN @jsonInput ELSE '[' + @jsonInput + ']' END;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (supp_cat_name NVARCHAR(50) '$.supp_cat_name')
        WHERE supp_cat_name IS NULL OR LTRIM(RTRIM(supp_cat_name)) = ''
    )
        THROW 50002, N'supp_cat_name is required for every row.', 1;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (supp_cat_name NVARCHAR(50) '$.supp_cat_name') j
        JOIN dbo.supplier_category m ON m.supp_cat_name = j.supp_cat_name AND m.is_active = 'Y'
    )
        THROW 50004, N'A supplier category with this name already exists.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @Inserted TABLE (supp_cat_sno INT);

        INSERT INTO dbo.supplier_category (supp_cat_name, supp_cat_code, is_active, created_date, created_by)
        OUTPUT INSERTED.supp_cat_sno INTO @Inserted
        SELECT supp_cat_name, supp_cat_code, 'Y', GETDATE(), created_by
        FROM OPENJSON(@json)
        WITH (
            supp_cat_name NVARCHAR(50)  '$.supp_cat_name',
            supp_cat_code NVARCHAR(100) '$.supp_cat_code',
            created_by    VARCHAR(20)   '$.created_by'
        );

        COMMIT TRANSACTION;

        SELECT t.* FROM dbo.supplier_category t JOIN @Inserted i ON i.supp_cat_sno = t.supp_cat_sno;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

