-- point a variant at an entity
-- {"module_code","variant_code","entity_code","modified_by","force"}
-- Re-pointing is held back (NEEDS_CONFIRM) while org scopes that have a workflow today would be left
-- with none under the new entity - creating that request there would then throw "no workflow".
CREATE OR ALTER   PROCEDURE dbo.sp_nt_SaveApprovalRoute
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0 THROW 52101, N'Invalid JSON payload.', 1;
    DECLARE @module NVARCHAR(50) = JSON_VALUE(@jsonInput, '$.module_code'),
            @variant NVARCHAR(50) = JSON_VALUE(@jsonInput, '$.variant_code'),
            @entity NVARCHAR(50) = JSON_VALUE(@jsonInput, '$.entity_code'),
            @by VARCHAR(20) = JSON_VALUE(@jsonInput, '$.modified_by'),
            @force BIT = CASE WHEN JSON_VALUE(@jsonInput, '$.force') IN ('true','1') THEN 1 ELSE 0 END;

    IF @module IS NULL OR @variant IS NULL OR @entity IS NULL THROW 52102, N'module_code, variant_code and entity_code are required.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.vw_approval_route_variant WHERE module_code = @module AND variant_code = @variant)
        THROW 52103, N'Unknown request type / variant.', 1;
    IF NOT EXISTS (SELECT 1 FROM dbo.entity_master WHERE entity_code = @entity AND is_active = 'Y' AND route_module_code = @module)
        THROW 52104, N'That approval type is not available for this kind of request.', 1;

    DECLARE @old NVARCHAR(50) = dbo.fn_resolve_approval_entity(@module, @variant);
    IF @old = @entity
    BEGIN
        SELECT N'UNCHANGED' AS status, @entity AS entity_code, CAST(0 AS INT) AS scopes_missing;
        RETURN;
    END;

    DECLARE @missing INT = (
        SELECT COUNT(*) FROM (
            SELECT DISTINCT wt.com_sno, wt.div_sno, wt.brn_sno, wt.dept_sno
            FROM dbo.workflow_types wt JOIN dbo.approval_workflow_master a ON a.workflow_id = wt.workflow_id
            WHERE a.entity_type = @old AND a.is_active = 'Y' AND wt.is_active = 'Y'
        ) o
        WHERE NOT EXISTS (
            SELECT 1 FROM dbo.workflow_types w2 JOIN dbo.approval_workflow_master b ON b.workflow_id = w2.workflow_id
            WHERE b.entity_type = @entity AND b.is_active = 'Y' AND w2.is_active = 'Y'
              AND w2.com_sno = o.com_sno AND w2.div_sno = o.div_sno AND w2.brn_sno = o.brn_sno AND w2.dept_sno = o.dept_sno));

    IF @missing > 0 AND @force = 0
    BEGIN
        SELECT N'NEEDS_CONFIRM' AS status, @entity AS entity_code, @missing AS scopes_missing;
        RETURN;
    END;

    MERGE dbo.approval_entity_route AS t
    USING (SELECT @module AS module_code, @variant AS variant_code) AS s
       ON t.module_code = s.module_code AND t.variant_code = s.variant_code
    WHEN MATCHED THEN UPDATE SET entity_code = @entity, is_active = 'Y', modified_by = @by, modified_at = GETDATE()
    WHEN NOT MATCHED THEN INSERT (module_code, variant_code, entity_code, modified_by) VALUES (@module, @variant, @entity, @by);

    SELECT N'SUCCESS' AS status, @entity AS entity_code, @missing AS scopes_missing;
END;

-- ============================================================================
-- ScreenMaster (screens: screen_id PK, is_active). screen_code stays
-- auto-generated ('S'+seq) and is not editable from Update.
-- ============================================================================
CREATE OR ALTER   PROCEDURE [dbo].[sp_nt_CreateScreenRecords]
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0
        THROW 50000, N'Invalid JSON payload provided.', 1;

    DECLARE @json NVARCHAR(MAX) = CASE WHEN LEFT(LTRIM(@jsonInput), 1) = '[' THEN @jsonInput ELSE '[' + @jsonInput + ']' END;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (screen_name VARCHAR(100) '$.screen_name')
        WHERE screen_name IS NULL OR LTRIM(RTRIM(screen_name)) = ''
    )
        THROW 50001, N'Screen name is required for every row.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @NextScreenNo INT;
        SELECT @NextScreenNo = ISNULL(MAX(CAST(SUBSTRING(screen_code, 2, LEN(screen_code)) AS INT)), 0)
        FROM dbo.screens
        WHERE LEFT(screen_code, 1) = 'S' AND ISNUMERIC(SUBSTRING(screen_code, 2, LEN(screen_code))) = 1;

        DECLARE @Rows TABLE (rn INT IDENTITY(1,1), screen_name VARCHAR(100), screen_code VARCHAR(10), parent_screen_id INT, display_order INT);
        INSERT INTO @Rows (screen_name, screen_code, parent_screen_id, display_order)
        SELECT
            LTRIM(RTRIM(screen_name)),
            CASE WHEN screen_code IS NULL OR LTRIM(RTRIM(screen_code)) = '' THEN NULL ELSE LTRIM(RTRIM(screen_code)) END,
            parent_screen_id,
            display_order
        FROM OPENJSON(@json)
        WITH (
            screen_name VARCHAR(100) '$.screen_name',
            screen_code VARCHAR(10) '$.screen_code',
            parent_screen_id INT '$.parent_screen_id',
            display_order INT '$.display_order'
        );

        UPDATE @Rows
        SET screen_code = 'S' + CAST(@NextScreenNo + rn AS VARCHAR(10))
        WHERE screen_code IS NULL;

        DECLARE @Inserted TABLE (screen_id INT);

        INSERT INTO dbo.screens (screen_name, screen_code, parent_screen_id, is_active, created_date, display_order)
        OUTPUT INSERTED.screen_id INTO @Inserted
        SELECT screen_name, screen_code, parent_screen_id, 'Y', GETDATE(), display_order
        FROM @Rows
        ORDER BY rn;

        COMMIT TRANSACTION;

        SELECT t.* FROM dbo.screens t JOIN @Inserted i ON i.screen_id = t.screen_id;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

-- create a dedicated approval type for one variant
-- {"module_code","variant_code","created_by"}  -> entity "<module>_<variant>" (idempotent).
CREATE OR ALTER   PROCEDURE dbo.sp_nt_CreateApprovalVariantEntity
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0 THROW 52101, N'Invalid JSON payload.', 1;
    DECLARE @module NVARCHAR(50) = JSON_VALUE(@jsonInput, '$.module_code'),
            @variant NVARCHAR(50) = JSON_VALUE(@jsonInput, '$.variant_code'),
            @by VARCHAR(20) = JSON_VALUE(@jsonInput, '$.created_by');
    DECLARE @vlabel NVARCHAR(100), @mlabel NVARCHAR(100);
    SELECT @vlabel = v.variant_label, @mlabel = m.module_label
    FROM dbo.vw_approval_route_variant v JOIN dbo.approval_route_module m ON m.module_code = v.module_code
    WHERE v.module_code = @module AND v.variant_code = @variant;
    IF @vlabel IS NULL THROW 52103, N'Unknown request type / variant.', 1;

    DECLARE @code NVARCHAR(50) = LEFT(@module + N'_' + @variant, 50);
    IF NOT EXISTS (SELECT 1 FROM dbo.entity_master WHERE entity_code = @code)
        INSERT INTO dbo.entity_master (entity_name, entity_code, entity_desc, is_active, created_by, route_module_code)
        VALUES (LEFT(@mlabel + N' - ' + @vlabel, 100), @code, N'Dedicated approval type for ' + @mlabel + N' / ' + @vlabel, 'Y', @by, @module);
    ELSE
        UPDATE dbo.entity_master SET is_active = 'Y', route_module_code = @module WHERE entity_code = @code;

    SELECT entity_sno, entity_code, entity_name FROM dbo.entity_master WHERE entity_code = @code;
END;

-- ============================================================================
-- ScreenPermission (permissions: permission_id PK, is_active). permission_code
-- stays auto-generated ('P'+seq) and is not editable from Update.
-- ============================================================================
CREATE OR ALTER   PROCEDURE [dbo].[sp_nt_CreatePermissionRecords]
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;
    IF ISJSON(@jsonInput) = 0
        THROW 50000, N'Invalid JSON payload provided.', 1;

    DECLARE @json NVARCHAR(MAX) = CASE WHEN LEFT(LTRIM(@jsonInput), 1) = '[' THEN @jsonInput ELSE '[' + @jsonInput + ']' END;

    IF EXISTS (
        SELECT 1 FROM OPENJSON(@json) WITH (permission_name NVARCHAR(255) '$.permission_name')
        WHERE permission_name IS NULL OR LTRIM(RTRIM(permission_name)) = ''
    )
        THROW 50001, N'permission_name is required for every row.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @NextPermNo INT;
        SELECT @NextPermNo = ISNULL(MAX(TRY_CAST(SUBSTRING(permission_code, 2, LEN(permission_code)) AS INT)), 0)
        FROM dbo.permissions
        WHERE LEFT(permission_code, 1) = 'P' AND ISNUMERIC(SUBSTRING(permission_code, 2, LEN(permission_code))) = 1;

        DECLARE @Rows TABLE (rn INT IDENTITY(1,1), permission_name NVARCHAR(255), permission_code VARCHAR(20), permission_description NVARCHAR(MAX));
        INSERT INTO @Rows (permission_name, permission_code, permission_description)
        SELECT
            LTRIM(RTRIM(permission_name)),
            CASE WHEN permission_code IS NULL OR LTRIM(RTRIM(permission_code)) = '' THEN NULL ELSE LTRIM(RTRIM(permission_code)) END,
            permission_description
        FROM OPENJSON(@json)
        WITH (
            permission_name NVARCHAR(255) '$.permission_name',
            permission_code NVARCHAR(50) '$.permission_code',
            permission_description NVARCHAR(MAX) '$.permission_description'
        );

        UPDATE @Rows
        SET permission_code = 'P' + CAST(@NextPermNo + rn AS VARCHAR(10))
        WHERE permission_code IS NULL;

        DECLARE @Inserted TABLE (permission_id INT);

        INSERT INTO dbo.permissions (permission_name, permission_code, permission_description, is_active)
        OUTPUT INSERTED.permission_id INTO @Inserted
        SELECT permission_name, permission_code, permission_description, 'Y'
        FROM @Rows
        ORDER BY rn;

        COMMIT TRANSACTION;

        SELECT t.* FROM dbo.permissions t JOIN @Inserted i ON i.permission_id = t.permission_id;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_CreatePOFromQuotation
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @pr_basic_sno       INT            = CAST(JSON_VALUE(@jsonInput, '$.pr_basic_sno') AS INT);
        DECLARE @vendor_sno         INT            = CAST(JSON_VALUE(@jsonInput, '$.vendor_sno') AS INT);
        DECLARE @com_sno            INT            = CAST(JSON_VALUE(@jsonInput, '$.com_sno') AS INT);
        DECLARE @div_sno            INT            = CAST(JSON_VALUE(@jsonInput, '$.div_sno') AS INT);
        DECLARE @brn_sno            INT            = CAST(JSON_VALUE(@jsonInput, '$.brn_sno') AS INT);
        DECLARE @dept_sno           INT            = CAST(JSON_VALUE(@jsonInput, '$.dept_sno') AS INT);
        DECLARE @budget_sno         INT            = CAST(JSON_VALUE(@jsonInput, '$.budget_sno') AS INT);
        DECLARE @budget_code        VARCHAR(20)    = LEFT(ISNULL(JSON_VALUE(@jsonInput, '$.budget_code'), ''), 20);
        DECLARE @priority_sno       INT            = CAST(JSON_VALUE(@jsonInput, '$.priority_sno') AS INT);
        DECLARE @po_date            DATE           = ISNULL(TRY_CAST(JSON_VALUE(@jsonInput, '$.po_date') AS DATE), CAST(GETDATE() AS DATE));
        DECLARE @required_date      DATE           = TRY_CAST(JSON_VALUE(@jsonInput, '$.required_date') AS DATE);
        DECLARE @purpose            VARCHAR(200)   = LEFT(ISNULL(JSON_VALUE(@jsonInput, '$.purpose'), ''), 200);
        DECLARE @terms_conditions   VARCHAR(MAX)   = JSON_VALUE(@jsonInput, '$.terms_conditions');
        DECLARE @delivery_address   VARCHAR(500)   = LEFT(ISNULL(JSON_VALUE(@jsonInput, '$.delivery_address'), ''), 500);
        DECLARE @split_pr_no        NVARCHAR(30)   = JSON_VALUE(@jsonInput, '$.split_pr_no');
        DECLARE @created_by         VARCHAR(20)    = JSON_VALUE(@jsonInput, '$.created_by');

        IF @pr_basic_sno IS NULL OR @vendor_sno IS NULL
            THROW 51001, 'pr_basic_sno and vendor_sno are required.', 1;

        DECLARE @pr_no VARCHAR(30);
        SELECT @pr_no = pr_no FROM pr_basic_info WHERE pr_basic_sno = @pr_basic_sno;
        IF @pr_no IS NULL
            THROW 51002, 'pr_no not found in pr_basic_info for given pr_basic_sno.', 1;

        IF @split_pr_no IS NULL SET @split_pr_no = @pr_no;

        -- No terms supplied (or blank) -> fall back to the scope's T&C master text.
        IF NULLIF(LTRIM(RTRIM(@terms_conditions)), '') IS NULL
            SET @terms_conditions = dbo.fn_nt_DefaultTermsText(@com_sno, @div_sno, @brn_sno, @dept_sno);

        IF NOT EXISTS (SELECT 1 FROM OPENJSON(@jsonInput, '$.items'))
            THROW 51003, 'No items found in JSON.', 1;

        INSERT INTO po_request_info (
            vendor_sno, brn_sno, dept_sno, com_sno, div_sno,
            budget_sno, budget_code, pr_basic_sno,
            po_date, required_date,
            priority_sno, purpose, terms_conditions, delivery_address,
            is_active, workflow_types_id, current_approver_id,
            status, po_df_no, split_pr_no
        )
        VALUES (
            @vendor_sno, @brn_sno, @dept_sno, @com_sno, @div_sno,
            @budget_sno, @budget_code, @pr_basic_sno,
            @po_date, @required_date,
            @priority_sno, @purpose, @terms_conditions, @delivery_address,
            'Y', 0, '0',
            'A', NULL, @split_pr_no
        );

        DECLARE @po_basic_sno INT = SCOPE_IDENTITY();
        DECLARE @po_no VARCHAR(30) = 'PO-' + CAST(YEAR(@po_date) AS VARCHAR(4)) + '-' + RIGHT('0000' + CAST(@po_basic_sno AS VARCHAR(10)), 4);

        UPDATE po_request_info SET po_df_no = @po_no WHERE po_basic_sno = @po_basic_sno;

        INSERT INTO po_item_details (
            po_basic_sno, pr_item_sno, prod_sno, prod_name,
            budget_sno, specification,
            qty, unit, unit_name,
            agreed_unit_price, total_cost,
            discount_pct, tax_pct, net_cost,
            remarks,
            created_by, created_date,
            is_active, split_pr_no
        )
        SELECT
            @po_basic_sno,
            TRY_CAST(JSON_VALUE(item.value, '$.pr_item_sno') AS INT),
            TRY_CAST(JSON_VALUE(item.value, '$.prod_sno') AS INT),
            LEFT(JSON_VALUE(item.value, '$.prod_name'), 200),
            @budget_sno,
            LEFT(ISNULL(JSON_VALUE(item.value, '$.specification'), ''), 200),
            TRY_CAST(JSON_VALUE(item.value, '$.qty') AS DECIMAL(18,4)),
            TRY_CAST(JSON_VALUE(item.value, '$.unit') AS INT),
            LEFT(JSON_VALUE(item.value, '$.unit_name'), 200),
            TRY_CAST(JSON_VALUE(item.value, '$.unit_price') AS DECIMAL(18,4)),
            ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.qty') AS DECIMAL(18,4)), 0)
                * ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.unit_price') AS DECIMAL(18,4)), 0),
            ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.discount_pct') AS DECIMAL(18,4)), 0),
            ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.tax_pct') AS DECIMAL(18,4)), 0),
            ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.total_amount') AS DECIMAL(18,4)),
                   ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.qty') AS DECIMAL(18,4)), 0)
                       * ISNULL(TRY_CAST(JSON_VALUE(item.value, '$.unit_price') AS DECIMAL(18,4)), 0)),
            LEFT(ISNULL(JSON_VALUE(item.value, '$.remarks'), ''), 200),
            @created_by, GETDATE(),
            'Y', @split_pr_no
        FROM OPENJSON(@jsonInput, '$.items') AS item;

        COMMIT TRANSACTION;

        SELECT
            @po_basic_sno AS po_basic_sno,
            @po_no        AS po_no,
            @pr_no        AS pr_no,
            @vendor_sno   AS vendor_sno,
            'SUCCESS'     AS result;

    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        SELECT
            ERROR_NUMBER()  AS ErrorNumber,
            ERROR_MESSAGE() AS ErrorMessage,
            ERROR_LINE()    AS ErrorLine,
            'FAILED'        AS result;
    END CATCH
END

CREATE OR ALTER   PROCEDURE dbo.sp_nt_GetNotifications
    @jsonInput NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ecno VARCHAR(50) = JSON_VALUE(@jsonInput, '$.ecno');
    IF @ecno IS NULL
    BEGIN
        RAISERROR('ecno is required.', 16, 1);
        RETURN;
    END

    SELECT TOP 200
        notif_id AS id, type, title, message, data, is_read AS [read],
        CONVERT(VARCHAR(30), created_at, 127) AS createdAt
    FROM dbo.nt_notifications
    WHERE ecno = @ecno
    ORDER BY created_at DESC, notif_sno DESC;
END;

