    DECLARE @id INT = TRY_CAST(JSON_VALUE(@jsonInput, '$.id') AS INT);
    IF @id IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.payment_terms_master WHERE payment_terms_sno = @id)
